svg.script:
(function(){
const svg=document.currentScript.ownerSVGElement;
const interactive='.gate, .channel-group, .center';
const flowControl=svg.getElementById('flow-control'),gateDemoControl=svg.getElementById('gate-demo-control');
const tooltip=svg.getElementById('svg-tooltip');
const tooltipRect=tooltip.querySelector('rect');
const tooltipText=tooltip.querySelector('text');
function hideTooltip(){tooltip.classList.remove('is-visible');tooltip.setAttribute('aria-hidden','true');}
function showTooltip(item,event){
 let detail=item.getAttribute('data-tooltip')||item.getAttribute('aria-label')||'';if(item.matches('.center')){const label=detail.split(/[—.]/)[0].trim(),state=item.dataset.hydraulicState||'balanced',pressure=item.dataset.hydraulicPressure||'0.00',occupancy=item.dataset.hydraulicOccupancy||'0',inflow=item.dataset.hydraulicInflow||'0.0',outflow=item.dataset.hydraulicOutflow||'0.0';detail=`${label}. ${detail} Hydraulic ${state}: pressure ${pressure}; ${occupancy} particles; inflow ${inflow}/s, outflow ${outflow}/s.`;}if(!detail)return;
 if(item.matches('.gate[data-transit-planets]'))detail+=` Current transit activation: ${item.dataset.transitPlanets}.`;
 if(item.matches('.channel-group[data-transit-channel]'))detail+=' Both gates are activated by the current transits.';
 const reference=item.matches('.gate')?`Gate ${item.dataset.gate}`:`Channel ${item.dataset.channel}`;
 const words=(reference+' '+detail).split(/\s+/),lines=[];let line='';
 words.forEach(word=>{const candidate=line?line+' '+word:word;if(candidate.length>42&&line){lines.push(line);line=word;}else line=candidate;});if(line)lines.push(line);
 while(tooltipText.firstChild)tooltipText.removeChild(tooltipText.firstChild);
 lines.forEach((value,index)=>{const span=document.createElementNS('http://www.w3.org/2000/svg','tspan');span.setAttribute('x','0');span.setAttribute('dy',index?'8':'0');span.textContent=value;tooltipText.appendChild(span);});
 const width=190,height=12+lines.length*8;tooltipRect.setAttribute('width',width);tooltipRect.setAttribute('height',height);tooltipText.setAttribute('transform','translate(6 9)');
 let screenX,screenY;if(event.type==='focusin'){const box=item.getBoundingClientRect();screenX=box.left+box.width/2;screenY=box.top+box.height/2;}else{screenX=event.clientX;screenY=event.clientY;}
 const bounds=svg.getBoundingClientRect();let anchorX=(screenX-bounds.left)*360/(bounds.width||360),anchorY=(screenY-bounds.top)*360/(bounds.height||360);
 if(!Number.isFinite(anchorX))anchorX=180;if(!Number.isFinite(anchorY))anchorY=180;
 const margin=8,maxX=360-width-margin,maxY=360-height-margin;const x=maxX;let y=anchorY+12;
 if(y>maxY)y=anchorY-height-12;y=Math.max(margin,Math.min(maxY,y));
 tooltip.setAttribute('transform',`translate(${x} ${y})`);tooltip.classList.add('is-visible');tooltip.setAttribute('aria-hidden','false');
}
let showAllFlow=true;
function positionGatesOnCenterBorders(){
 const rootPoint=(element,x,y)=>{const point=svg.createSVGPoint();point.x=x;point.y=y;return point.matrixTransform(element.getCTM());};
 const polygonFor=shape=>{
  const points=[];
  if(shape.points){for(let i=0;i<shape.points.numberOfItems;i++){const point=shape.points.getItem(i);points.push(rootPoint(shape,point.x,point.y));}}
  else{const x=Number(shape.getAttribute('x')),y=Number(shape.getAttribute('y')),w=Number(shape.getAttribute('width')),h=Number(shape.getAttribute('height'));[[x,y],[x+w,y],[x+w,y+h],[x,y+h]].forEach(([px,py])=>points.push(rootPoint(shape,px,py)));}
  return points;
 };
 const centers=new Map();svg.querySelectorAll('.center').forEach(center=>{const shape=center.querySelector('.center-shape');if(shape)centers.set(center.dataset.center,polygonFor(shape));});
 const nearestEdge=(point,vertices)=>{let best=null;for(let i=0;i<vertices.length;i++){const a=vertices[i],b=vertices[(i+1)%vertices.length],dx=b.x-a.x,dy=b.y-a.y,len2=dx*dx+dy*dy||1,t=Math.max(0,Math.min(1,((point.x-a.x)*dx+(point.y-a.y)*dy)/len2)),projected={x:a.x+t*dx,y:a.y+t*dy},distance=Math.hypot(point.x-projected.x,point.y-projected.y);if(!best||distance<best.distance)best={edge:i,t,distance};}return best;};
 const buckets=new Map();svg.querySelectorAll('.gate').forEach(gate=>{const vertices=centers.get(gate.dataset.center),marker=gate.querySelector('.gate-marker');if(!vertices||!marker)return;const point=rootPoint(marker,Number(marker.getAttribute('cx')),Number(marker.getAttribute('cy')));let nearest;if(gate.dataset.center==='ajna'&&['47','24','4'].includes(gate.dataset.gate)){nearest={edge:0,t:Math.max(0,Math.min(1,(point.x-vertices[0].x)/(vertices[1].x-vertices[0].x)))}}else if(gate.dataset.center==='ego'){const own=vertices.reduce((sum,p)=>({x:sum.x+p.x/vertices.length,y:sum.y+p.y/vertices.length}),{x:0,y:0}),dirs=[];svg.querySelectorAll('.channel-group').forEach(channel=>{const from=channel.dataset.from,to=channel.dataset.to;if(from!==gate.dataset.gate&&to!==gate.dataset.gate)return;const partner=svg.getElementById('gate-'+(from===gate.dataset.gate?to:from)),partnerCenter=partner&&centers.get(partner.dataset.center);if(partnerCenter){const target=partnerCenter.reduce((sum,p)=>({x:sum.x+p.x/partnerCenter.length,y:sum.y+p.y/partnerCenter.length}),{x:0,y:0}),dx=target.x-own.x,dy=target.y-own.y,len=Math.hypot(dx,dy)||1;dirs.push({x:dx/len,y:dy/len});}});if(dirs.length){const direction=dirs.reduce((sum,d)=>({x:sum.x+d.x/dirs.length,y:sum.y+d.y/dirs.length}),{x:0,y:0}),len=Math.hypot(direction.x,direction.y)||1,dx=direction.x/len,dy=direction.y/len;let hit=null;for(let edge=0;edge<vertices.length;edge++){const a=vertices[edge],b=vertices[(edge+1)%vertices.length],ex=b.x-a.x,ey=b.y-a.y,den=dx*ey-dy*ex;if(Math.abs(den)<1e-8)continue;const rx=a.x-own.x,ry=a.y-own.y,t=(rx*ey-ry*ex)/den,u=(rx*dy-ry*dx)/den;if(t>=0&&u>=0&&u<=1&&(!hit||t<hit.t))hit={edge,t,u};}nearest=hit?{edge:hit.edge,t:hit.u}:nearestEdge(point,vertices);}else nearest=nearestEdge(point,vertices);}else nearest=nearestEdge(point,vertices);const key=`${gate.dataset.center}:${nearest.edge}`;if(!buckets.has(key))buckets.set(key,[]);buckets.get(key).push({gate,vertices,...nearest});});
 const placements=new Map(),place=(gate,vertices,edge,desired)=>{const inverse=gate.getCTM().inverse(),local=svg.createSVGPoint();local.x=desired.x;local.y=desired.y;const target=local.matrixTransform(inverse);gate.querySelectorAll('.gate-hit,.gate-marker,.gate-number').forEach(node=>{node.setAttribute('cx',target.x.toFixed(3));node.setAttribute('cy',target.y.toFixed(3));});placements.set(gate.dataset.gate,{vertices,edge,desired});};
 buckets.forEach(items=>{items.sort((a,b)=>a.t-b.t);const a=items[0].vertices[items[0].edge],b=items[0].vertices[(items[0].edge+1)%items[0].vertices.length];items.forEach((item,index)=>{const t=items.length===1?item.t:.12+.76*(index/(items.length-1)),desired={x:a.x+(b.x-a.x)*t,y:a.y+(b.y-a.y)*t};place(item.gate,item.vertices,item.edge,desired);});});
 const parent=new Map(),find=id=>{if(!parent.has(id))parent.set(id,id);if(parent.get(id)!==id)parent.set(id,find(parent.get(id)));return parent.get(id);},join=(a,b)=>{const ra=find(a),rb=find(b);if(ra!==rb)parent.set(ra,rb);};
 svg.querySelectorAll('.channel-group').forEach(channel=>{const d=channel.querySelector('.channel')?.getAttribute('d')||'',m=d.match(/^M\s*(-?[\d.]+),(-?[\d.]+)\s*C\s*(-?[\d.]+),(-?[\d.]+)\s+(-?[\d.]+),(-?[\d.]+)\s+(-?[\d.]+),(-?[\d.]+)$/);if(!m)return;const xs=[Number(m[1]),Number(m[3]),Number(m[5]),Number(m[7])];if(Math.max(...xs)-Math.min(...xs)<=8)join(channel.dataset.from,channel.dataset.to);});
 const components=new Map();parent.forEach((_,id)=>{const root=find(id);if(!components.has(root))components.set(root,[]);components.get(root).push(id);});
 components.forEach(ids=>{if(ids.length<2)return;const edges=ids.map(id=>placements.get(id)).filter(Boolean);if(edges.length!==ids.length)return;let low=-Infinity,high=Infinity;edges.forEach(item=>{const a=item.vertices[item.edge],b=item.vertices[(item.edge+1)%item.vertices.length];low=Math.max(low,Math.min(a.x,b.x));high=Math.min(high,Math.max(a.x,b.x));});if(low>high)return;const targetX=Math.max(low,Math.min(high,edges.reduce((sum,item)=>sum+item.desired.x,0)/edges.length));edges.forEach((item,index)=>{const a=item.vertices[item.edge],b=item.vertices[(item.edge+1)%item.vertices.length],dx=b.x-a.x,desired={x:targetX,y:Math.abs(dx)<1e-6?item.desired.y:a.y+(targetX-a.x)*(b.y-a.y)/dx};place(svg.getElementById('gate-'+ids[index]),item.vertices,item.edge,desired);});});
}
function pointInGroup(marker,group){const point=svg.createSVGPoint();point.x=Number(marker.getAttribute('cx'));point.y=Number(marker.getAttribute('cy'));return point.matrixTransform(group.getCTM().inverse().multiply(marker.getCTM()));}
function setLaneGeometry(){
 svg.querySelectorAll('.channel-group').forEach(group=>{
  const base=group.querySelector('.channel');if(!base)return;
  const match=base.getAttribute('d').match(/^M\s*(-?[\d.]+),(-?[\d.]+)\s*C\s*(-?[\d.]+),(-?[\d.]+)\s+(-?[\d.]+),(-?[\d.]+)\s+(-?[\d.]+),(-?[\d.]+)$/);if(!match)return;
  const [x0,y0,x1,y1,x2,y2,x3,y3]=match.slice(1).map(Number),from=svg.getElementById('gate-'+group.dataset.from),to=svg.getElementById('gate-'+group.dataset.to);if(!from||!to)return;
  const fromMarker=from.querySelector('.gate-marker'),toMarker=to.querySelector('.gate-marker');if(!fromMarker||!toMarker)return;
  const fp=pointInGroup(fromMarker,group),tp=pointInGroup(toMarker,group),startIsFrom=Math.hypot(x0-fp.x,y0-fp.y)+Math.hypot(x3-tp.x,y3-tp.y)<=Math.hypot(x0-tp.x,y0-tp.y)+Math.hypot(x3-fp.x,y3-fp.y);
  const start=startIsFrom?fp:tp,end=startIsFrom?tp:fp,dx0=start.x-x0,dy0=start.y-y0,dx3=end.x-x3,dy3=end.y-y3;
  const vertical=Math.abs(start.x-end.x)<.02,egoLinked=from.dataset.center==='ego'||to.dataset.center==='ego',c1x=vertical?start.x:egoLinked?start.x+(end.x-start.x)/3:x1+dx0,c2x=vertical?start.x:egoLinked?start.x+2*(end.x-start.x)/3:x2+dx3,c1y=egoLinked?start.y+(end.y-start.y)/3:y1+dy0,c2y=egoLinked?start.y+2*(end.y-start.y)/3:y2+dy3;
  const d=`M${start.x.toFixed(3)},${start.y.toFixed(3)} C${c1x.toFixed(3)},${c1y.toFixed(3)} ${c2x.toFixed(3)},${c2y.toFixed(3)} ${end.x.toFixed(3)},${end.y.toFixed(3)}`;
  group.querySelectorAll('path').forEach(path=>path.setAttribute('d',d));
 });
}
positionGatesOnCenterBorders();
setLaneGeometry();
function centerBaseColor(center){const shape=center?.querySelector('.center-shape');return shape?.getAttribute('data-base-fill')||shape?.getAttribute('fill')||'#888888';}
function setFlowDirections(){
 const defs=svg.querySelector('defs'),ns='http://www.w3.org/2000/svg';
 svg.querySelectorAll('.channel-group').forEach(group=>{
  const main=group.querySelector('.channel-flow'),line=group.querySelector('.channel');if(!main||!line)return;
  const a=main.getPointAtLength(0),b=main.getPointAtLength(main.getTotalLength()),fromGate=svg.getElementById('gate-'+group.dataset.from),toGate=svg.getElementById('gate-'+group.dataset.to),fromMarker=fromGate?.querySelector('.gate-marker'),toMarker=toGate?.querySelector('.gate-marker');if(!fromMarker||!toMarker)return;
  const from=pointInGroup(fromMarker,group),to=pointInGroup(toMarker,group),startIsFrom=Math.hypot(a.x-from.x,a.y-from.y)<=Math.hypot(b.x-from.x,b.y-from.y),sourceCenter=svg.getElementById('center-'+fromGate.dataset.center),sinkCenter=svg.getElementById('center-'+toGate.dataset.center),sourceColor=centerBaseColor(sourceCenter),sinkColor=centerBaseColor(sinkCenter),channelColor=({integration:'#91bca3',individual:'#858873',tribal:'#c99d74',logic:'#405d70',abstract:'#a45d64'})[group.dataset.circuit]||'#858873',isActive=gate=>Boolean(gate&&(gate.hasAttribute('data-activation')||gate.hasAttribute('data-transit-planets')||gate.dataset.demoActive==='true')),fromActive=isActive(fromGate),toActive=isActive(toGate),gradientId='channel-gradient-'+group.dataset.channel;
  let gradient=svg.getElementById(gradientId);if(!gradient){gradient=document.createElementNS(ns,'linearGradient');gradient.id=gradientId;gradient.setAttribute('gradientUnits','userSpaceOnUse');defs.appendChild(gradient);}gradient.setAttribute('x1',from.x.toFixed(3));gradient.setAttribute('y1',from.y.toFixed(3));gradient.setAttribute('x2',to.x.toFixed(3));gradient.setAttribute('y2',to.y.toFixed(3));gradient.replaceChildren();const stops=fromActive&&!toActive?[[0,sourceColor,1],[.38,sourceColor,.9],[.62,channelColor,.42],[1,channelColor,.42]]:!fromActive&&toActive?[[0,channelColor,.42],[.38,channelColor,.42],[.62,sinkColor,.9],[1,sinkColor,1]]:fromActive&&toActive?[[0,sourceColor,1],[1,sinkColor,1]]:[[0,channelColor,.42],[1,channelColor,.42]];stops.forEach(([offset,color,opacity])=>{const stop=document.createElementNS(ns,'stop');stop.setAttribute('offset',String(offset));stop.setAttribute('stop-color',color);stop.setAttribute('stop-opacity',String(opacity));gradient.appendChild(stop);});line.style.stroke=`url(#${gradientId})`;
  const markerId='channel-arrowhead-'+group.dataset.channel;let marker=svg.getElementById(markerId);if(!marker){marker=document.createElementNS(ns,'marker');marker.id=markerId;marker.setAttribute('viewBox','0 0 9 6');marker.setAttribute('markerWidth','9');marker.setAttribute('markerHeight','6');marker.setAttribute('refX','9');marker.setAttribute('refY','3');marker.setAttribute('orient','auto-start-reverse');marker.setAttribute('markerUnits','userSpaceOnUse');const triangle=document.createElementNS(ns,'path');triangle.setAttribute('d','M0,0 L6,3 L0,6 Z');marker.appendChild(triangle);defs.appendChild(marker);}marker.querySelector('path').setAttribute('fill',sourceColor);marker.querySelector('path').setAttribute('fill-opacity','1');
  group.dataset.flowSourcePosition=startIsFrom?'start':'end';main.classList.toggle('flow-forward',startIsFrom);main.classList.toggle('flow-backward',!startIsFrom);line.removeAttribute('marker-start');line.removeAttribute('marker-end');line.setAttribute(startIsFrom?'marker-end':'marker-start',`url(#${markerId})`);
 });
}
setFlowDirections();
function refreshCenterFlowTextures(){svg.querySelectorAll('.center').forEach(center=>{const shape=center.querySelector('.center-shape');if(!shape)return;const base=shape.getAttribute('data-base-fill')||shape.getAttribute('fill');if(!shape.hasAttribute('data-base-fill'))shape.setAttribute('data-base-fill',base);shape.style.setProperty('--chakra-color',base);shape.setAttribute('fill','#000000');svg.getElementById('center-flow-gradient-'+center.dataset.center)?.remove();svg.getElementById('center-flow-clip-'+center.dataset.center)?.remove();center.querySelector('.center-flow-texture')?.remove();});}

function refreshCenterInternalLinks(){
 const ns='http://www.w3.org/2000/svg',defs=svg.querySelector('defs'),centers=Array.from(svg.querySelectorAll('.center')),incoming=new Map(),outgoing=new Map(),active=gate=>Boolean(gate&&(gate.hasAttribute('data-activation')||gate.hasAttribute('data-transit-planets')||gate.dataset.demoActive==='true'));
 svg.querySelectorAll('.channel-group').forEach(channel=>{const from=svg.getElementById('gate-'+channel.dataset.from),to=svg.getElementById('gate-'+channel.dataset.to);if(!from||!to||!(channel.dataset.defined==='true'||channel.hasAttribute('data-transit-channel')||(active(from)&&active(to))))return;const source=svg.getElementById('center-'+from.dataset.center),sink=svg.getElementById('center-'+to.dataset.center);if(!source||!sink||source===sink)return;if(!outgoing.has(source))outgoing.set(source,[]);if(!incoming.has(sink))incoming.set(sink,[]);outgoing.get(source).push({gate:from,channel});incoming.get(sink).push({gate:to,channel});});
 centers.forEach(center=>{const id=center.dataset.center,shape=center.querySelector('.center-shape'),layerId='center-internal-links-'+id,clipId='center-internal-clip-'+id;let layer=center.querySelector('.center-internal-links');if(layer)layer.replaceChildren();const sinks=incoming.get(center)||[],sources=outgoing.get(center)||[],pairs=new Map();const localPoint=gate=>pointInGroup(gate.querySelector('.gate-marker'),center);sinks.forEach(sink=>{const a=localPoint(sink.gate);let best=null;sources.forEach(source=>{if(source.gate===sink.gate)return;const b=localPoint(source.gate),distance=Math.hypot(b.x-a.x,b.y-a.y);if(!best||distance<best.distance)best={source,distance};});if(best)pairs.set(`${sink.gate.dataset.gate}-${best.source.gate.dataset.gate}`,{sink:sink.gate,source:best.source.gate});});sources.forEach(source=>{const b=localPoint(source.gate);let best=null;sinks.forEach(sink=>{if(sink.gate===source.gate)return;const a=localPoint(sink.gate),distance=Math.hypot(b.x-a.x,b.y-a.y);if(!best||distance<best.distance)best={sink,distance};});if(best)pairs.set(`${best.sink.gate.dataset.gate}-${source.gate.dataset.gate}`,{sink:best.sink.gate,source:source.gate});});if(!pairs.size){layer?.remove();svg.getElementById(clipId)?.remove();return;}if(!shape)return;if(!layer){layer=document.createElementNS(ns,'g');layer.setAttribute('class','center-internal-links');layer.setAttribute('id',layerId);layer.setAttribute('pointer-events','none');let clip=svg.getElementById(clipId);if(!clip){clip=document.createElementNS(ns,'clipPath');clip.id=clipId;clip.setAttribute('clipPathUnits','userSpaceOnUse');const silhouette=shape.cloneNode(false);silhouette.removeAttribute('class');silhouette.removeAttribute('filter');silhouette.removeAttribute('stroke');silhouette.removeAttribute('stroke-width');silhouette.setAttribute('fill','#fff');clip.appendChild(silhouette);defs.appendChild(clip);}layer.setAttribute('clip-path',`url(#${clipId})`);center.insertBefore(layer,shape.nextSibling);}const base=centerBaseColor(center);Array.from(pairs.values()).forEach((pair,index)=>{const a=localPoint(pair.sink),b=localPoint(pair.source),distance=Math.hypot(b.x-a.x,b.y-a.y);if(distance<1.5)return;const dx=(b.x-a.x)/distance,dy=(b.y-a.y)/distance,px=-dy,py=dx,bend=(index%2?1:-1)*Math.min(2.5,distance*.13),x1=a.x+dx*distance*.33+px*bend,y1=a.y+dy*distance*.33+py*bend,x2=a.x+dx*distance*.67+px*bend,y2=a.y+dy*distance*.67+py*bend,gradientId=`center-link-gradient-${id}-${pair.sink.dataset.gate}-${pair.source.dataset.gate}`;let gradient=svg.getElementById(gradientId);if(!gradient){gradient=document.createElementNS(ns,'linearGradient');gradient.id=gradientId;gradient.setAttribute('gradientUnits','userSpaceOnUse');defs.appendChild(gradient);}gradient.setAttribute('x1',a.x.toFixed(2));gradient.setAttribute('y1',a.y.toFixed(2));gradient.setAttribute('x2',b.x.toFixed(2));gradient.setAttribute('y2',b.y.toFixed(2));gradient.replaceChildren();[[0,mixFlowColor(base,.22)],[1,mixFlowColor(base,-.18)]].forEach(([offset,color])=>{const stop=document.createElementNS(ns,'stop');stop.setAttribute('offset',String(offset));stop.setAttribute('stop-color',color);gradient.appendChild(stop);});const path=document.createElementNS(ns,'path');path.setAttribute('d',`M${a.x.toFixed(2)},${a.y.toFixed(2)} C${x1.toFixed(2)},${y1.toFixed(2)} ${x2.toFixed(2)},${y2.toFixed(2)} ${b.x.toFixed(2)},${b.y.toFixed(2)}`);path.setAttribute('fill','none');path.setAttribute('stroke',`url(#${gradientId})`);path.setAttribute('stroke-width','1.35');path.setAttribute('stroke-opacity','.88');path.setAttribute('stroke-linecap','round');layer.appendChild(path);});if(pairs.size&&!window.matchMedia('(prefers-reduced-motion: reduce)').matches){const particles=document.createElementNS(ns,'g');particles.setAttribute('class','chakra-particles');particles.dataset.sources=Array.from(new Set(Array.from(pairs.values(),pair=>pair.source.dataset.gate))).join(',');particles.setAttribute('data-bounds',shape.tagName==='polygon'?shape.getAttribute('points'):JSON.stringify({x:Number(shape.getAttribute('x')),y:Number(shape.getAttribute('y')),w:Number(shape.getAttribute('width')),h:Number(shape.getAttribute('height'))}));const bounds=shape.getBBox();if(id==='sacral'){particles.dataset.origin='sacral';particles.dataset.count='10';}layer.appendChild(particles);}if(!layer.childElementCount){layer.remove();svg.getElementById(clipId)?.remove();}});
}
function runChakraParticlePhysics(){
 const ns='http://www.w3.org/2000/svg',graph=svg.getElementById('bodygraph-art'),sacral=svg.getElementById('center-sacral');if(!graph||!sacral)return;
 const particleLayer=document.createElementNS(ns,'g');particleLayer.setAttribute('id','continuous-flow-particles');particleLayer.setAttribute('pointer-events','none');graph.appendChild(particleLayer);
 const flowTypes=[{id:'generator',name:'Generator',short:'Generator',description:'Steady Sacral source',sacralDefined:true,initialSacral:96,initialAmbient:240,ambientMax:260,emissionInterval:320,ambientInterval:2400,channelSpeed:1,pressureGain:1,pressureRelaxation:1.4,sacralFloor:.45,sinkAttraction:1},{id:'mg',name:'Manifesting Generator',short:'MG',description:'Sacral · throat boost',sacralDefined:true,initialSacral:96,initialAmbient:240,ambientMax:260,emissionInterval:320,ambientInterval:2400,channelSpeed:1,pressureGain:1,pressureRelaxation:1.4,sacralFloor:.45,sinkAttraction:1},{id:'projector',name:'Projector',short:'Projector',description:'External energy · no Sacral source',sacralDefined:false,initialSacral:0,initialAmbient:240,ambientMax:260,emissionInterval:Infinity,ambientInterval:1000,channelSpeed:1,pressureGain:.72,pressureRelaxation:1.2,sacralFloor:0,sinkAttraction:1.3},{id:'reflector',name:'Reflector',short:'Reflector',description:'Environmental sample · 30s cycle',sacralDefined:false,initialSacral:0,initialAmbient:240,ambientMax:260,emissionInterval:Infinity,ambientInterval:4200,channelSpeed:1,pressureGain:.45,pressureRelaxation:.55,sacralFloor:0,sinkAttraction:1.1}];let flowTypeIndex=1,activeFlowType=flowTypes[flowTypeIndex];const flowTypeControl=svg.getElementById('flow-type-control'),flowTypeDescription=svg.getElementById('flow-type-description'),flowPressureSummary=svg.getElementById('flow-pressure-summary');const flowPressureComparisonA=svg.getElementById('flow-pressure-comparison-a'),flowPressureComparisonB=svg.getElementById('flow-pressure-comparison-b'),pressureHistory=new Map(flowTypes.map(type=>[type.id,{mean:null,count:0}]));function formatTypePressure(id){const value=pressureHistory.get(id)?.mean;return value===null||value===undefined?'—':value.toFixed(2);}function updatePressureComparison(){flowPressureComparisonA.textContent=`G ${formatTypePressure('generator')} · MG ${formatTypePressure('mg')}`;flowPressureComparisonB.textContent=`P ${formatTypePressure('projector')} · R ${formatTypePressure('reflector')}`;}
 const centerStats=new Map(),centers=Array.from(svg.querySelectorAll('.center'));
