function updateDefinedChannels(){svg.querySelectorAll('.channel-group').forEach(channel=>{const from=svg.getElementById('gate-'+channel.dataset.from),to=svg.getElementById('gate-'+channel.dataset.to),isActive=gate=>Boolean(gate&&(gate.hasAttribute('data-activation')||gate.hasAttribute('data-transit-planets')||gate.dataset.demoActive==='true'));channel.dataset.defined=String(Boolean(isActive(from)&&isActive(to))||channel.hasAttribute('data-transit-channel'));channel.classList.toggle('is-partial',isActive(from)!==isActive(to));});setFlowDirections();svg.querySelectorAll('.center').forEach(center=>{const connected=Array.from(svg.querySelectorAll('.channel-group')).some(channel=>channel.dataset.defined==='true'&&(svg.getElementById('gate-'+channel.dataset.from)?.dataset.center===center.dataset.center||svg.getElementById('gate-'+channel.dataset.to)?.dataset.center===center.dataset.center));center.dataset.defined=String(connected);const state=connected?'Defined':'Open';const label=center.getAttribute('aria-label')||center.dataset.center;center.setAttribute('aria-label',label.replace(/center\s+[—-]\s+(Defined|Open)/,`center — ${state}`));});}
function enableAllGatesForDemo(){svg.querySelectorAll('.gate').forEach(gate=>{gate.dataset.demoActive='true';gate.dataset.state='closed';});updateDefinedChannels();gateDemoControl.setAttribute('aria-pressed','true');gateDemoControl.setAttribute('aria-label','All gates demo on; activate to toggle');gateDemoControl.querySelector('text').textContent='Demo gates: ON';refreshFlowTextures();}
function restoreActualGateStates(){svg.querySelectorAll('.gate').forEach(gate=>{gate.removeAttribute('data-demo-active');gate.dataset.state=gate.hasAttribute('data-activation')||gate.hasAttribute('data-transit-planets')?'closed':'open';});updateDefinedChannels();gateDemoControl.setAttribute('aria-pressed','false');gateDemoControl.setAttribute('aria-label','All gates demo off; activate to toggle');gateDemoControl.querySelector('text').textContent='Demo gates: OFF';refreshFlowTextures();}
restoreActualGateStates();
function mixFlowColor(color,amount){const match=(color||'').match(/^#([\da-f]{6})$/i);if(!match)return color;const target=amount>=0?255:0,magnitude=Math.abs(amount),rgb=[0,2,4].map(index=>Math.round(parseInt(match[1].slice(index,index+2),16)*(1-magnitude)+target*magnitude));return '#'+rgb.map(value=>value.toString(16).padStart(2,'0')).join('');}
function refreshFlowTextures(){refreshCenterFlowTextures();svg.querySelectorAll('.center-internal-links').forEach(layer=>layer.remove());svg.querySelectorAll('[id^="center-internal-clip-"],[id^="center-link-gradient-"]').forEach(el=>el.remove());}
refreshFlowTextures();
runChakraParticlePhysics();
const flowTextureObserver=new MutationObserver(refreshFlowTextures);flowTextureObserver.observe(svg,{subtree:true,attributes:true,attributeFilter:['data-activation','data-transit-planets','data-transit-channel','data-defined']});
function syncFlow(){svg.querySelectorAll('.channel-group').forEach(ch=>ch.classList.toggle('is-flowing',ch.dataset.defined==='true'&&(showAllFlow||ch.classList.contains('is-active'))));const particles=svg.getElementById('continuous-flow-particles');if(particles)particles.style.display=showAllFlow?'':'none';flowControl.setAttribute('aria-pressed',String(showAllFlow));flowControl.querySelector('text').textContent=showAllFlow?'Ⅱ  Pause flow':'▶  Flow';}
syncFlow();
function toggleFlow(){showAllFlow=!showAllFlow;syncFlow();}
function toggleGateDemo(){if(gateDemoControl.getAttribute('aria-pressed')!=='true')enableAllGatesForDemo();else restoreActualGateStates();syncFlow();}
gateDemoControl.addEventListener('click',toggleGateDemo);gateDemoControl.addEventListener('keydown',event=>{if(event.key==='Enter'||event.key===' '){event.preventDefault();toggleGateDemo();}});
flowControl.addEventListener('click',toggleFlow);
flowControl.addEventListener('keydown',event=>{if(event.key==='Enter'||event.key===' '){event.preventDefault();toggleFlow();}});
function clear(){svg.querySelectorAll('.is-active,.is-related').forEach(el=>el.classList.remove('is-active','is-related'));syncFlow();}
function activate(el){
 clear();
 if(!el)return;
 const channels=el.matches('.channel-group')?[el]:Array.from(svg.querySelectorAll('.channel-group')).filter(ch=>ch.dataset.from===el.dataset.gate||ch.dataset.to===el.dataset.gate);
 const gateIds=new Set();
 channels.forEach(ch=>{ch.classList.add('is-active');gateIds.add(ch.dataset.from);gateIds.add(ch.dataset.to);});syncFlow();
 gateIds.forEach(id=>{const gate=svg.getElementById('gate-'+id);if(gate)gate.classList.add(el.id==='gate-'+id?'is-active':'is-related');});
 svg.querySelectorAll('.center').forEach(center=>{if(Array.from(gateIds).some(id=>svg.getElementById('gate-'+id)?.dataset.center===center.dataset.center))center.classList.add('is-active');});
}
function fromTarget(target){return target instanceof Element?target.closest(interactive):null;}
function updateZoomLabels(){const zoom=svg.getScreenCTM()?.a||1;svg.querySelectorAll('.gate-number').forEach(label=>label.classList.toggle('is-zoomed',zoom>=3));}
updateZoomLabels();window.addEventListener('resize',updateZoomLabels);window.CastaliaHumanDesignTransit?.installSvg(svg);
svg.addEventListener('pointerover',event=>{const item=fromTarget(event.target);if(item){activate(item);showTooltip(item,event);}});
svg.addEventListener('pointerout',event=>{const item=fromTarget(event.target);if(item&&!item.contains(event.relatedTarget)){const next=fromTarget(event.relatedTarget);if(next){activate(next);showTooltip(next,event);}else{clear();hideTooltip();}}});
svg.addEventListener('focusin',event=>{const item=fromTarget(event.target);if(item){activate(item);showTooltip(item,event);}});
svg.addEventListener('focusout',event=>{if(!fromTarget(event.relatedTarget)){clear();hideTooltip();}else{const next=fromTarget(event.relatedTarget);activate(next);showTooltip(next,event);}});
})();
